import {scenarioAllowsBackground} from './scenario-background-rules.js?v=bungalow-style-1';
// Manual pp.90,92,106: petitioner offers, stipend while standing, and casino crime.
// Eligibility, size, stipend and crime falloff are original calibration.
export const BUSINESSES={casino:{name:'Casino',size:3,cost:0,upkeep:0,sprite:64,stipend:150},toxicWaste:{name:'Toxic Waste Conversion Plant',size:3,cost:0,upkeep:0,sprite:70,stipend:300}};
const freshOffer=()=>({offered:null,accepted:false,declinedUntil:0});
export const freshBusiness=()=>({...freshOffer(),toxicWaste:freshOffer()});
export const businessOffer=(c,type='casino')=>type==='casino'?c.business:c.business.toxicWaste;
export function advanceBusiness(c){if(!scenarioAllowsBackground(c,'automaticBusiness'))return false;let offered=false;for(const [type,months,pop]of [['casino',6,128],['toxicWaste',12,256]]){const b=businessOffer(c,type);if(b.offered!==null||b.accepted||c.month<b.declinedUntil||c.month<months||c.stats.population<pop||c.stats.balance>=0)continue;b.offered=c.month;offered=true;}return offered;}
export function answerBusiness(c,accept,type='casino'){if(!Object.hasOwn(BUSINESSES,type))return{ok:false,error:'Unknown business offer.'};const b=businessOffer(c,type);if(typeof accept!=='boolean'||b.offered===null||b.accepted)return{ok:false,error:'There is no pending business offer.'};if(accept)b.accepted=true;else{b.offered=null;b.declinedUntil=c.month+12;}return{ok:true};}
export function businessRoots(c){const n=Math.sqrt(c.tiles.length);return c.tiles.filter(t=>BUSINESSES[t.type]&&t.root===t.y*n+t.x);}
export function businessStats(c){const roots=businessRoots(c);return{businessBuildings:roots.length,businessIncome:roots.reduce((v,t)=>v+BUSINESSES[t.type].stipend,0)};}
export function casinoCrime(roots,t){return roots.filter(b=>b.type==='casino').reduce((v,b)=>v+Math.max(0,18*(1-Math.hypot(t.x-b.x-1,t.y-b.y-1)/8)),0);}
function validateOffer(v,month){if(!v||typeof v.accepted!=='boolean'||v.offered!==null&&(!Number.isInteger(v.offered)||v.offered<0||v.offered>month)||v.accepted&&v.offered===null||!Number.isInteger(v.declinedUntil)||v.declinedUntil<0||v.declinedUntil>month+12)throw Error('Invalid business offer.');return{offered:v.offered,accepted:v.accepted,declinedUntil:v.declinedUntil};}

export function validateBusiness(v,month,version=46){return{...validateOffer(v,month),toxicWaste:version>=46?validateOffer(v.toxicWaste,month):freshOffer()};}

export function businessIncomeRows(c){const roots=businessRoots(c);return Object.entries(BUSINESSES).map(([type,d])=>{const offer=businessOffer(c,type),count=roots.filter(t=>t.type===type).length;return{type,name:d.name,count,income:count*d.stipend,status:count?'Paying':offer.accepted?'Permit accepted; not placed':offer.offered!==null?'Offer awaiting decision':'No permit',impact:type==='casino'?'Raises nearby crime.':'Adds air and water pollution; may originate enabled toxic clouds.'};});}
export function businessIncomeReport(c){const rows=businessIncomeRows(c),total=rows.reduce((sum,row)=>sum+row.income,0),money=n=>'§'+n.toLocaleString();return `<details><summary>Business income breakdown · ${money(total)}/month</summary><div class="table-scroll"><table><thead><tr><th scope="col">Facility</th><th scope="col">Status</th><th scope="col">Buildings</th><th scope="col">Monthly income</th><th scope="col">Local effect</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.name}</th><td>${r.status}</td><td>${r.count}</td><td>${money(r.income)}</td><td>${r.impact}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row" colspan="3">Total business income</th><td>${money(total)}</td><td></td></tr></tfoot></table></div><p>These are current monthly payments, included in the Business deals income line above. Accepted permits earn nothing until placed. Demolition or destruction ends that facility’s payment. Pollution and crime effects are not deducted from the stipend; they affect the city through its simulation.</p></details>`;}
